/** Node-style errors used by the portable `node:net` shim. */
import { AbortError, codedError, deprecatedNodeApi, invalidArgType, invalidArgValue, missingArgs, outOfRange, unsupportedNodeApi, } from "../errors/core.js";
export { AbortError, invalidArgType, invalidArgValue, missingArgs, outOfRange };
export function invalidAddress() {
    return codedError(new Error("Invalid socket address"), "ERR_INVALID_ADDRESS");
}
export function serverAlreadyListening() {
    return codedError(new Error("Listen method has been called more than once without closing."), "ERR_SERVER_ALREADY_LISTEN");
}
export function serverNotRunning() {
    return codedError(new Error("Server is not running."), "ERR_SERVER_NOT_RUNNING");
}
export function socketClosed() {
    return codedError(new Error("Socket is closed"), "ERR_SOCKET_CLOSED");
}
export function socketClosedBeforeConnection() {
    return codedError(new Error("Socket closed before the connection was established"), "ERR_SOCKET_CLOSED_BEFORE_CONNECTION");
}
export function socketHandleAdopted() {
    return codedError(new Error("This socket handle has already been bound to another socket"), "ERR_SOCKET_HANDLE_ADOPTED");
}
export function ipBlocked(address) {
    return codedError(new Error(`IP ${address} is blocked`), "ERR_IP_BLOCKED");
}
export function unsupported(api, reason) {
    throw unsupportedNodeApi(api, reason);
}
export function deprecated(api, replacement) {
    throw deprecatedNodeApi(api, replacement);
}
